settings.custom_liquid:
{% assign deadline = '2026-09-28T23:30:00-04:00' %}

<style>
  .aga-batch {
    max-width: 760px; margin: 0 auto; text-align: center; color: #2F2A22;
    padding: clamp(56px, 8vw, 92px) 20px;
  }
  .aga-batch__added {
    margin: 0 0 clamp(16px, 2.6vw, 22px); color: #B4693C;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 11px; font-weight: 600; letter-spacing: .18em; text-transform: uppercase;
  }
  .aga-batch__title {
    margin: 0; color: #2F2A22;
    font-family: var(--font-accent--family, Lora, serif);
    font-weight: 400; font-size: clamp(22px, 4.4vw, 30px); line-height: 1.25;
  }
  .aga-batch__timer {
    display: flex; justify-content: center; max-width: 520px;
    margin: clamp(26px, 4vw, 38px) auto 0;
  }
  .aga-batch__unit { position: relative; flex: 1 1 0; padding: 0 clamp(6px, 2vw, 16px); }
  .aga-batch__unit + .aga-batch__unit::before {
    content: ""; position: absolute; left: 0; top: 4%; bottom: 20%;
    width: 1px; background: rgb(47 42 34 / .14);
  }
  .aga-batch__num {
    display: block; color: #2F2A22;
    font-family: var(--font-accent--family, Lora, serif);
    font-weight: 400; font-size: clamp(30px, 8vw, 48px); line-height: 1;
    font-variant-numeric: tabular-nums; font-feature-settings: "tnum" 1;
  }
  .aga-batch__lbl {
    display: block; margin-top: clamp(8px, 1.6vw, 12px); color: #56503F;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 10px; font-weight: 500; letter-spacing: .18em; text-transform: uppercase;
  }
  .aga-batch__sub {
    margin: clamp(26px, 4vw, 36px) auto 0; max-width: 44ch; color: #56503F;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 15px; font-weight: 400; line-height: 1.65;
  }
  .aga-batch__cta {
    display: inline-block; margin-top: clamp(24px, 3.5vw, 32px);
    padding: 15px 34px; border-radius: 2px; background: #5C6B4C; color: #FBF8F2;
    font-family: var(--font-body--family, "Work Sans", sans-serif);
    font-size: 12px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase;
    text-decoration: none; transition: background-color .2s ease;
  }
  .aga-batch__cta:hover, .aga-batch__cta:focus { background: #4A573D; color: #FBF8F2; }
  @media (max-width: 420px) {
    .aga-batch__lbl { font-size: 9px; letter-spacing: .12em; }
  }
</style>

<section class="aga-batch" data-deadline="{{ deadline }}">
  <p class="aga-batch__added">3 more days added to this batch</p>

  <h2 class="aga-batch__title">This batch closes in</h2>

  <div class="aga-batch__timer">
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="d">--</span><span class="aga-batch__lbl">Days</span></div>
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="h">--</span><span class="aga-batch__lbl">Hours</span></div>
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="m">--</span><span class="aga-batch__lbl">Min</span></div>
    <div class="aga-batch__unit"><span class="aga-batch__num" data-u="s">--</span><span class="aga-batch__lbl">Sec</span></div>
  </div>

  <p class="aga-batch__sub">Every batch is repriced to supply and demand &mdash; up or down. Yours is locked the moment you order.</p>
  <a class="aga-batch__cta" href="/collections/pre-order">Lock in this batch&rsquo;s price</a>
</section>

<script>
(function () {
  function init(box) {
    if (box.getAttribute('data-ready')) return;
    box.setAttribute('data-ready', '1');
    var end = new Date(box.getAttribute('data-deadline')).getTime();
    var q = function (sel) { return box.querySelector(sel); };
    var pad = function (n) { return (n < 10 ? '0' : '') + n; };
    function tick() {
      var left = end - Date.now();
      if (isNaN(end) || left <= 0) {
        clearInterval(timer);
        q('.aga-batch__timer').style.display = 'none';
        q('.aga-batch__added').style.display = 'none';
        q('.aga-batch__title').textContent = 'This batch has closed';
        q('.aga-batch__sub').textContent = 'The next batch opens at new pricing. Ready-to-ship plants are available now.';
        q('.aga-batch__cta').textContent = 'Shop ready to ship';
        q('.aga-batch__cta').href = '/collections/ready-to-ship-tissue-culture';
        return;
      }
      var s = Math.floor(left / 1000);
      q('[data-u="d"]').textContent = pad(Math.floor(s / 86400));
      q('[data-u="h"]').textContent = pad(Math.floor(s % 86400 / 3600));
      q('[data-u="m"]').textContent = pad(Math.floor(s % 3600 / 60));
      q('[data-u="s"]').textContent = pad(s % 60);
    }
    var timer = setInterval(tick, 1000);
    tick();
  }
  function run() {
    var all = document.querySelectorAll('.aga-batch');
    for (var i = 0; i < all.length; i++) init(all[i]);
  }
  run();
  document.addEventListener('DOMContentLoaded', run);
  document.addEventListener('shopify:section:load', run);
})();
</script>
